package com.afaq.iman;
import android.os.Bundle;import android.graphics.Color;import android.graphics.drawable.ColorDrawable;import android.view.View;import androidx.core.graphics.Insets;import androidx.core.view.ViewCompat;import androidx.core.view.WindowCompat;import androidx.core.view.WindowInsetsCompat;import com.getcapacitor.BridgeActivity;
public class MainActivity extends BridgeActivity{@Override protected void onCreate(Bundle b){registerPlugin(PrayerWidgetPlugin.class);registerPlugin(SystemSettingsPlugin.class);registerPlugin(TasbeehWidgetPlugin.class);super.onCreate(b);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);getWindow().setBackgroundDrawable(new ColorDrawable(Color.rgb(245,248,246)));View content=findViewById(android.R.id.content);ViewCompat.setOnApplyWindowInsetsListener(content,(v,insets)->{Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return WindowInsetsCompat.CONSUMED;});ViewCompat.requestApplyInsets(content);}}
